import sys
import gc
import multiprocessing as mp


def make_tree(depth):
    if not depth:
        return None, None
    depth -= 1
    return make_tree(depth), make_tree(depth)


def check_tree(node):
    l = node[0]
    if l is None:
        return 1
    return 1 + check_tree(l) + check_tree(node[1])


def check_group(depth, n):
    c = 0
    for _ in range(n):
        c += check_tree(make_tree(depth))
    return f"{n}\t trees of depth {depth}\t check: {c}"


def main():
    gc.disable()
    n = int(sys.argv[1])
    min_depth = 4
    max_depth = max(min_depth + 2, n)
    stretch_depth = max_depth + 1

    print(f"stretch tree of depth {stretch_depth}\t check: {check_tree(make_tree(stretch_depth))}")

    long_lived_tree = make_tree(max_depth)

    mmd = max_depth + min_depth
    tasks = [(d, 1 << (mmd - d)) for d in range(min_depth, stretch_depth, 2)]

    try:
        with mp.Pool(initializer=gc.disable) as pool:
            results = pool.starmap(check_group, tasks)
    except Exception:
        results = [check_group(d, iters) for d, iters in tasks]

    for line in results:
        print(line)

    print(f"long lived tree of depth {max_depth}\t check: {check_tree(long_lived_tree)}")


if __name__ == "__main__":
    main()
