import sys


def read_sequence():
    content = sys.stdin.buffer.read()
    if not content:
        return ""
    idx = content.find(b">THREE")
    if idx == -1:
        return ""
    start = content.find(b"\n", idx)
    if start == -1:
        return ""
    start += 1
    end = content.find(b">", start)
    if end == -1:
        seq_bytes = content[start:]
    else:
        seq_bytes = content[start:end]

    seq_bytes = (
        seq_bytes.replace(b"\n", b"")
        .replace(b"\r", b"")
        .replace(b" ", b"")
        .upper()
    )
    return seq_bytes.decode("ascii")


def count_overlapping(seq, sub):
    count = 0
    start = 0
    while True:
        idx = seq.find(sub, start)
        if idx == -1:
            return count
        count += 1
        start = idx + 1


def print_frequencies(seq, k):
    total = len(seq) - k + 1
    if total <= 0:
        print()
        return

    if k == 1:
        chars = sorted(set(seq))
        counts = {c: seq.count(c) for c in chars}
    elif k == 2:
        chars = sorted(set(seq))
        counts = {}
        for c1 in chars:
            for c2 in chars:
                kmer = c1 + c2
                cnt = count_overlapping(seq, kmer)
                if cnt > 0:
                    counts[kmer] = cnt

    sorted_kmers = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    for kmer, cnt in sorted_kmers:
        pct = (cnt * 100.0) / total
        print(f"{kmer} {pct:.3f}")
    print()


def main():
    _ = int(sys.argv[1]) if len(sys.argv) > 1 else 0

    seq = read_sequence()

    print_frequencies(seq, 1)
    print_frequencies(seq, 2)

    fragments = [
        "GGT",
        "GGTA",
        "GGTATT",
        "GGTATTTTAATT",
        "GGTATTTTAATTTATAGT",
    ]

    for fragment in fragments:
        cnt = count_overlapping(seq, fragment)
        print(f"{cnt}\t{fragment}")


if __name__ == "__main__":
    main()
